import { IToken } from 'hooks/auth/state'
import {
  setChromeLocalData,
} from 'hooks/chrome-storage-change-data'
import { extractExpireTime } from 'utils/auth-token'
import { getItemFromCache } from 'utils/cacheUtils'

const sendEvent = new Event('sendTokenToExtension')

async function checkWebExtensionIntegrationAuth() {
  await setChromeLocalData({
    checkAuthState: {
      state: 'loading',
      message: 'Verificando autenticação.',
    },
  })
  const token = await getItemFromCache<IToken>('token')
  const webStorage = localStorage.getItem('tk')

  if (token) {
    await setChromeLocalData({
      checkAuthState: {
        state: 'redirecting',
        message:
          'Você já está logado na extensão. Redirecionando para página principal da extensão.',
      },
    })
    return setTimeout(async () => {
      await setChromeLocalData({
        checkAuthState: {
          state: 'finished',
          message: '',
        },
      })
    }, 1000)
  }

  if (!webStorage)
    return await setChromeLocalData({
      checkAuthState: {
        state: 'finished',
        message: '',
      },
    })

  const expireIn = extractExpireTime(webStorage)

  await setChromeLocalData({
    token: JSON.stringify({
      access_token: webStorage,
      expire_in: expireIn,
    }),
    checkAuthState: {
      state: 'finished',
      message: '',
    },
  })
}

window.addEventListener('sendTokenToExtension', checkWebExtensionIntegrationAuth)

window.dispatchEvent(sendEvent)

export {}
