import { base64ToJSON } from './base64'

export function extractExpireTime(token?: string | null) {
  if (!token) return console.error('Empty token!')

  const splitedToken = token.split('.')

  if (!splitedToken[1]) return console.error('Invalid token!')

  const parsedToken = base64ToJSON(splitedToken[1])

  if (!parsedToken) return console.error('Cannot parse token!')

  return parsedToken?.exp * 1000
}
